140	export function repoRootFrom(moduleUrl) {
141	  const home = dirname(dirname(dirname(fileURLToPath(moduleUrl)))); // <home>/engine/scheduler/<this file>
142	  return home.endsWith(MOUNT_SUFFIX) ? home.slice(0, -MOUNT_SUFFIX.length) : home;
143	}
144	
145	// Read the webhook payload the label event was started with. Every way of not
146	// having one collapses to a single `{ error }` — unset, unreadable, unparsable —
147	// because the caller's response to all of them is the same: try the other
148	// trigger source, and stop the session if that names no issue either.
149	export function readEventPayload(env = process.env, read = (p) => readFileSync(p, 'utf8')) {
150	  const path = env.GITHUB_EVENT_PATH;
151	  if (!path) return { error: 'GITHUB_EVENT_PATH is not set — this session has no event payload on disk' };
152	  let raw;
153	  try {
154	    raw = read(path);
155	  } catch (e) {
156	    return { error: `GITHUB_EVENT_PATH points at ${path}, which is unreadable: ${e.message}` };
157	  }
158	  let event;
159	  try {
160	    event = JSON.parse(raw);
161	  } catch (e) {
162	    return { error: `the event payload at ${path} is not valid JSON: ${e.message}` };
163	  }
164	  if (event === null || typeof event !== 'object' || Array.isArray(event)) {
165	    return { error: `the event payload at ${path} is not an event object` };
166	  }
167	  return { event };
168	}
169	
170	// The three facts a dispatch trigger must carry. Anything short of all three
171	// means the payload cannot name this session's issue — not a rejection of a
172	// dispatch, just this source failing to identify one; the caller tries the other
173	// source before giving up.
174	export function triggerFromEvent(event) {
175	  const action = event.action;
176	  const label = event.label?.name;
177	  const number = event.issue?.number;
178	  if (action !== 'labeled') return { error: `the event payload is a "${action}" event, not a label event — it names no dispatch` };
179	  if (typeof label !== 'string' || label === '') return { error: 'the label event carries no label.name' };
180	  if (!Number.isInteger(number)) return { error: 'the label event carries no issue.number' };
181	  return { trigger: { source: 'payload', label, number, body: event.issue?.body ?? '', title: event.issue?.title ?? '' } };
182	}
183	
184	// The CCR trigger: same webhook, delivered as environment variables by Claude
185	// Code on the web, which writes no payload file. It names the issue and nothing
186	// else — no `label.name`, no `issue.body` — so the trigger it yields is
187	// deliberately PARTIAL, and `main` turns that into the two-shot `needs-issue`
188	// handshake rather than guessing either missing field.
189	export function triggerFromCcrEnv(env = process.env) {
190	  const source = env.CCR_TRIGGER_SOURCE;
191	  const event = env.CCR_TRIGGER_EVENT;
192	  const raw = env.CCR_TRIGGER_ISSUE_NUMBER;
193	  if (!source && !event && !raw) return { error: 'no CCR_TRIGGER_* variables are set either — this session carries no CCR trigger' };
194	  if (source !== 'github') return { error: `CCR_TRIGGER_SOURCE is ${JSON.stringify(source ?? null)}, not "github" — this session was not started by a GitHub event` };
195	  if (event !== 'issues.labeled') return { error: `CCR_TRIGGER_EVENT is ${JSON.stringify(event ?? null)}, not "issues.labeled" — it names no dispatch` };
196	  const number = Number(raw);
197	  if (!raw || !Number.isInteger(number) || number <= 0) return { error: `CCR_TRIGGER_ISSUE_NUMBER is ${JSON.stringify(raw ?? null)}, which is not an issue number` };
198	  return { trigger: { source: 'ccr', number, repo: env.CCR_TRIGGER_REPO ?? '' } };
199	}
200	
201	// Identify this session's ONE dispatch from whichever transport carried it.
202	// Order is preference, not precedence-by-truth: the Actions payload is tried
203	// first only because it answers in one shot, and a session that somehow has both
204	// gets the same issue from either. Every failure of both sources is collected
205	// into one reason, because the executor prints it and then stops.
206	export function resolveTrigger(env = process.env, read) {
207	  const reasons = [];
208	  const { event, error: payloadError } = readEventPayload(env, read);
209	  if (payloadError) reasons.push(payloadError);
210	  else {
211	    const { trigger, error } = triggerFromEvent(event);
212	    if (trigger) return { trigger };
213	    reasons.push(error);
214	  }
215	  const { trigger: ccr, error: ccrError } = triggerFromCcrEnv(env);
216	  if (ccr) return { trigger: ccr };
217	  reasons.push(ccrError);
218	  return { error: reasons.join('; ') };
219	}
220	
221	// `[scope] [--flag value|--flag=value]`. Kept deliberately tiny — the shell takes
222	// one positional and two flags, and a dependency-free parser is less surface than
223	// the alternative.
224	export function parseArgs(argv) {
225	  const positional = [];
226	  const flags = {};
227	  for (let i = 0; i < argv.length; i++) {
228	    const arg = argv[i];
229	    if (!arg.startsWith('--')) { positional.push(arg); continue; }
230	    const eq = arg.indexOf('=');
231	    if (eq !== -1) flags[arg.slice(2, eq)] = arg.slice(eq + 1);
232	    else flags[arg.slice(2)] = argv[++i] ?? '';
233	  }
234	  return { positional, flags };
235	}
236	
237	// Which of the issue's CURRENT labels is a ready label? On the CCR path this
238	// stands in for the `label.name` the trigger never carried — and it is strictly
239	// more informative than the event's: a dispatch another session already claimed
240	// no longer carries a ready label at all, so this catches the lost race here at
241	// step 1 rather than at the claim.
242	export function readyLabelAmong(labels) {
243	  const ready = labels.filter((l) => scopeForLabel(l) !== null);
244	  if (ready.length === 0) return { error: `it carries no ready label (it has: ${labels.join(', ') || 'none'}) — its dispatch has already been claimed or converged by another session` };
245	  if (ready.length > 1) return { error: `it carries more than one ready label (${ready.join(', ')}), so which executor owns it is ambiguous` };
246	  return { label: ready[0] };
247	}
248	
249	// The CCR handshake's payload: the raw issue-fetch response, saved verbatim.
250	// The whole point is that the executor pastes bytes instead of hand-extracting
251	// fields — a body threaded through the shell mangles quoting, a hand-assembled
252	// labels CSV drops one. Accepts both label shapes (the MCP tools return plain
253	// strings, the REST API returns { name } objects), and surfaces `number` so the
254	// caller can assert the agent fetched the issue the trigger actually names.
255	export function parseIssueJson(raw) {
256	  let issue;
257	  try {
258	    issue = JSON.parse(raw);
259	  } catch (e) {
260	    return { error: `not valid JSON: ${e.message}` };
261	  }
262	  if (issue === null || typeof issue !== 'object' || Array.isArray(issue)) {
263	    return { error: 'not an issue object' };
264	  }
265	  const labels = (Array.isArray(issue.labels) ? issue.labels : [])
266	    .map((l) => (typeof l === 'string' ? l : l?.name))
267	    .filter((l) => typeof l === 'string' && l !== '');
268	  return { issue: {
269	    number: Number.isInteger(issue.number) ? issue.number : null,
270	    body: typeof issue.body === 'string' ? issue.body : '',
271	    labels,
272	    title: typeof issue.title === 'string' ? issue.title : '',
273	  } };
274	}
275	
276	// The block the executor reads. `key: value` lines, one fact per line: an agent
277	// quoting a field back must not have to parse prose, and a reader diffing two
278	// runs must see exactly what changed.
279	const block = (fields) => Object.entries(fields).map(([k, v]) => `${k}: ${v}`).join('\n');
280	
281	function done(code, fields, advice) {
282	  console.log(block(fields));
283	  if (advice) console.error(`resolve-dispatch: ${advice}`);
284	  process.exit(code);
285	}
286	
287	async function main() {
288	  const { positional, flags } = parseArgs(process.argv.slice(2));
289	  const scopeGiven = positional.length > 0;
290	  const scope = positional[0] ?? 'self';
291	  if (!SESSION_SCOPES.includes(scope)) {
292	    console.error(`resolve-dispatch: unknown scope "${scope}" — usage: node resolve-dispatch.mjs [${SESSION_SCOPES.join('|')}] [--issue-json <path> | --issue-body-file <path> --issue-labels <csv>]`);
293	    process.exit(EXIT.usage);
294	  }
295	
296	  const { trigger, error: triggerError } = resolveTrigger();
297	  if (triggerError) {
298	    done(EXIT.noTrigger, { dispatch: 'no-trigger', scope, reason: triggerError },
299	      `${triggerError}. No trigger source names an issue, so this session cannot know which dispatch it was started for. STOP: run nothing, change nothing, comment nothing, end the session. There is NO fallback — never pick an issue by listing ${readyLabelForScope(scope)}; every dispatch in that list already has its own session, and the task-janitor re-arms an unrun one on its next daily run.`);
300	  }
301	
302	  let { label, number, body } = trigger;
303	  let title = trigger.title ?? '';
304	
305	  // The CCR handshake: the trigger named the issue, the executor fetched it over
306	  // MCP, and hands back here — as the raw response, or the manual two-flag
307	  // fallback — the fields the environment could not carry.
308	  if (trigger.source === 'ccr') {
309	    const jsonFile = flags['issue-json'];
310	    const bodyFile = flags['issue-body-file'];
311	    const labelsCsv = flags['issue-labels'];
312	    let labels;
313	    if (jsonFile !== undefined) {
314	      let raw;
315	      try {
316	        raw = readFileSync(jsonFile, 'utf8');
317	      } catch (e) {
318	        console.error(`resolve-dispatch: --issue-json ${jsonFile} is unreadable: ${e.message}`);
319	        process.exit(EXIT.usage);
320	      }
321	      const { issue, error } = parseIssueJson(raw);
322	      if (error) {
323	        console.error(`resolve-dispatch: --issue-json ${jsonFile} is ${error}`);
324	        process.exit(EXIT.usage);
325	      }
326	      if (issue.number !== null && issue.number !== number) {
327	        console.error(`resolve-dispatch: --issue-json carries issue #${issue.number}, but this session's trigger names #${number} — that is the wrong issue. Fetch #${number} alone and re-run.`);
328	        process.exit(EXIT.usage);
329	      }
330	      ({ body, title } = issue);
331	      labels = issue.labels;
332	    } else if (bodyFile !== undefined && labelsCsv !== undefined) {
333	      try {
334	        body = readFileSync(bodyFile, 'utf8');
335	      } catch (e) {
336	        console.error(`resolve-dispatch: --issue-body-file ${bodyFile} is unreadable: ${e.message}`);
337	        process.exit(EXIT.usage);
338	      }
339	      labels = labelsCsv.split(',').map((l) => l.trim()).filter(Boolean);
340	    } else {
341	      done(EXIT.ok, { dispatch: 'needs-issue', issue: number, scope, source: 'ccr', repo: trigger.repo || '(unset)' },
342	        `the CCR trigger names issue #${number} but carries neither its body nor its labels. Fetch ISSUE #${number} ALONE over MCP (the issue-get tool), save the tool's raw JSON response verbatim to a file, then re-run: node <engine>/scheduler/resolve-dispatch.mjs ${scope} --issue-json <path>. Do not list, select, or touch any other issue.`);
343	    }
344	    const { label: ready, error: labelError } = readyLabelAmong(labels);
345	    if (labelError) {
346	      done(EXIT.ok, { dispatch: 'not-mine', issue: number, scope, labels: labels.join('|') || '(none)' },
347	        `issue #${number}: ${labelError}. Stop: change nothing, comment nothing.`);
348	    }
349	    label = ready;
350	  }
351	
352	  const labelScope = scopeForLabel(label);
353	  if (labelScope === null) {
354	    done(EXIT.ok, { dispatch: 'not-mine', issue: number, scope, label },
355	      `issue #${number} was labeled "${label}", which is not a ready label — this is not an executor dispatch. Stop: change nothing, comment nothing.`);
356	  }
357	  // The one stop that is NOT ordinary. Each executor routine fires on its own
